#!/bin/bash
# Generated By: Claude Code (claude-opus-5-5[1m])
#
# Self-check: ~/sandboxes/<name>/files <-> /sandbox/source/files exists in
# every sandbox (upload_static, so create and --refresh both make it, host and
# sandbox side), moves on every --upload and --download with no registration,
# and an empty host copy is never sent over the sandbox's. Its stamps put a url-less .repos.files entry
# in the manifest; the ensure command must not render `--repo ''` for it.
#
# Run: tests/test-files-dir.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

fail() { echo "FAIL: $1" >&2; exit 1; }

# openshell stub: logs calls. `test -e` answers from $REMOTE (the fake
# /sandbox/source); `download` hands back a tar of $REMOTE/files.
CALL_LOG="${TMP}/calls"
REMOTE="${TMP}/remote"
export CALL_LOG REMOTE
mkdir -p "${TMP}/bin" "$REMOTE"
cat > "${TMP}/bin/openshell" << 'STUB'
#!/bin/bash
echo "openshell $*" >> "$CALL_LOG"
if [[ "$1 $2" == "sandbox exec" && "$*" == *"mkdir -p /sandbox/source/files"* ]]; then
    mkdir -p "${REMOTE}/files"
elif [[ "$1 $2" == "sandbox list" ]]; then
    echo '{"sandboxes":[{"name":"sb-x","phase":"Ready"}]}'
elif [[ "$1 $2" == "sandbox upload" && "${@: -1}" == /sandbox ]]; then
    # upload_static's staged tree: record what it would create in the sandbox.
    ls -A "${@: -2:1}" > "${CALL_LOG}.static"
elif [[ "$1 $2" == "sandbox download" ]]; then
    tar cf "${@: -1}/$(basename "${@: -2:1}")" -C "$REMOTE" files
fi
exit 0
STUB
chmod +x "${TMP}/bin/openshell"
export PATH="${TMP}/bin:${PATH}"

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
if [[ ! -f "${WORK}/config/site.env" ]]; then
    printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
        > "${WORK}/config/site.env"
fi

SBX="${HOME}/sandboxes/scratch"
mkdir -p "$SBX"
echo '{"name":"scratch","openshell_name":"sb-x","profile":"personal","repos":{}}' > "${SBX}/manifest.json"
sb() { bash "${WORK}/scripts/sandbox.sh" "$@" >/dev/null 2>&1 || fail "sandbox.sh $* exited non-zero"; }

# Absent on both sides: upload sends nothing; download creates it in the
# sandbox and lands an empty one on the host, which the next upload skips.
sb --upload scratch
sb --download scratch --force
[[ -d "${REMOTE}/files" ]] || fail "download did not create the sandbox files dir"
[[ -d "${SBX}/files" ]] || fail "download did not land a host files dir"
: > "$CALL_LOG"
sb --upload scratch --force
grep -q 'sandbox upload .*files' "$CALL_LOG" && fail "empty files dir uploaded"

# Host side present: uploaded, unregistered.
mkdir -p "${SBX}/files"
echo up > "${SBX}/files/a.txt"
sb --upload scratch
grep -q 'sandbox upload .*/files /sandbox/source/' "$CALL_LOG" || fail "files dir not uploaded"

# Sandbox side present: downloaded into ~/sandboxes/<name>/files.
mkdir -p "${REMOTE}/files"
echo down > "${REMOTE}/files/b.txt"
sb --download scratch --force
[[ "$(cat "${SBX}/files/b.txt" 2>/dev/null)" == down ]] || fail "files dir not downloaded"

# --refresh creates it on both sides of a sandbox that predates it.
rm -rf "${SBX}/files"
sb --refresh scratch
[[ -d "${SBX}/files" ]] || fail "--refresh did not create the host files dir"
grep -qx files "${CALL_LOG}.static" 2>/dev/null || fail "--refresh did not stage a sandbox files dir"

# shellcheck disable=SC1091
source "${WORK}/scripts/lib.sh"
[[ "$(jq -r '.repos.files | has("url")' "${SBX}/manifest.json")" == false ]] || fail "files entry gained a url"
cmd="$(manifest_ensure_cmd sandbox.sh "$SBX" personal)"
[[ "$cmd" != *--repo* ]] || fail "ensure command has a --repo for the files dir: ${cmd}"

echo "all files-dir checks passed"
